#!/usr/bin/env node
// Regenerates agent-repl's copy of pi-repl from a pi-repl checkout.
//
// Nothing is rewritten by hand. pi-repl's index.ts is copied verbatim except for
// the module specifiers of its two Pi package imports, which point at
// src/pi-compat (small MIT-licensed copies of the Pi helpers it uses). Its
// shared/ directory and its tests are copied unchanged apart from import paths,
// so pi-repl's own test suite runs against this copy.
//
// Usage: node scripts/sync-from-pi-repl.mjs [../pi-repl]
import { execFileSync } from "node:child_process";
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, relative, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const upstream = resolve(process.argv[2] ?? join(root, "..", "pi-repl"));
const piAgent = join(upstream, "node_modules", "@earendil-works", "pi-coding-agent");
const piAi = join(upstream, "node_modules", "@earendil-works", "pi-ai");
for (const required of [join(upstream, "index.ts"), piAgent, piAi]) {
	if (!existsSync(required)) throw new Error(`Missing ${required}. Run npm install in the pi-repl checkout first.`);
}
const read = path => readFileSync(path, "utf8");
const pkg = JSON.parse(read(join(upstream, "package.json")));
let commit = "unknown";
try { commit = execFileSync("git", ["-C", upstream, "rev-parse", "--short", "HEAD"], { encoding: "utf8" }).trim(); } catch {}
const piAgentVersion = JSON.parse(read(join(piAgent, "package.json"))).version;
const piAiVersion = JSON.parse(read(join(piAi, "package.json"))).version;

function replaceExactly(text, from, to, expectedCount, label) {
	const count = text.split(from).length - 1;
	if (count !== expectedCount) throw new Error(`${label}: expected ${expectedCount} occurrence(s) of ${JSON.stringify(from)}, found ${count}. pi-repl changed; update this script.`);
	return text.split(from).join(to);
}

// 1. The extension, with only its Pi import specifiers redirected.
let source = read(join(upstream, "index.ts"));
source = replaceExactly(source, `from "@earendil-works/pi-coding-agent";`, `from "./pi-compat/index.js";`, 2, "index.ts");
source = replaceExactly(source, `from "@earendil-works/pi-ai";`, `from "./pi-compat/index.js";`, 1, "index.ts");
if (/@earendil-works\//.test(source)) throw new Error("index.ts has another Pi import; extend pi-compat and this script.");
writeFileSync(join(root, "src", "pi-repl.ts"),
	`// GENERATED by scripts/sync-from-pi-repl.mjs from pi-repl ${pkg.version} (${commit}). Do not edit by hand:\n`
	+ `// change pi-repl and re-sync. Identical to pi-repl's index.ts except that its Pi\n`
	+ `// imports come from ./pi-compat/index.js.\n` + source);

// 2. shared/, verbatim.
rmSync(join(root, "src", "shared"), { recursive: true, force: true });
cpSync(join(upstream, "shared"), join(root, "src", "shared"), { recursive: true });

// 3. Pi helpers (MIT, Mario Zechner / earendil-works), verbatim apart from paths.
const compat = join(root, "src", "pi-compat");
mkdirSync(compat, { recursive: true });
// LICENSE in src/pi-compat is Pi's licence, which these copies carry.
const banner = (from, version) => `// Copied from ${from} ${version} (MIT License, (c) 2025 Mario Zechner; see LICENSE).\n// Regenerated by scripts/sync-from-pi-repl.mjs; do not edit by hand.\n`;
for (const ext of ["js", "d.ts"]) {
	writeFileSync(join(compat, `truncate.${ext}`), banner("@earendil-works/pi-coding-agent dist/core/tools/truncate", piAgentVersion)
		+ read(join(piAgent, "dist", "core", "tools", `truncate.${ext}`)).replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n"));
	writeFileSync(join(compat, `exec.${ext}`), banner("@earendil-works/pi-coding-agent dist/core/exec", piAgentVersion)
		+ read(join(piAgent, "dist", "core", `exec.${ext}`)).replace(`from "../utils/child-process.js"`, `from "./child-process.js"`).replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n"));
	writeFileSync(join(compat, `string-enum.${ext}`), banner("@earendil-works/pi-ai dist/utils/typebox-helpers", piAiVersion)
		+ read(join(piAi, "dist", "utils", `typebox-helpers.${ext}`)).replace(/\n\/\/# sourceMappingURL=.*\n?$/, "\n"));
}
// child-process.js: only waitForChildProcess; its Windows spawn wrapper needs cross-spawn.
const childProcess = read(join(piAgent, "dist", "utils", "child-process.js"));
const start = childProcess.indexOf("const EXIT_STDIO_GRACE_MS");
const end = childProcess.indexOf("//# sourceMappingURL");
if (start < 0 || !childProcess.includes("export function waitForChildProcess")) throw new Error("child-process.js changed; update this script.");
writeFileSync(join(compat, "child-process.js"), banner("@earendil-works/pi-coding-agent dist/utils/child-process (waitForChildProcess only)", piAgentVersion)
	+ childProcess.slice(start, end < 0 ? undefined : end).trimEnd() + "\n");
writeFileSync(join(compat, "child-process.d.ts"), banner("@earendil-works/pi-coding-agent dist/utils/child-process (waitForChildProcess only)", piAgentVersion)
	+ `import type { ChildProcess } from "node:child_process";\nexport declare function waitForChildProcess(child: ChildProcess): Promise<number | null>;\n`);

// 4. pi-repl's tests, with import paths pointing at this copy.
const testRoot = join(root, "test", "upstream");
rmSync(testRoot, { recursive: true, force: true });
const copyTests = (from, to) => {
	mkdirSync(to, { recursive: true });
	for (const name of readdirSync(from)) {
		const path = join(from, name), target = join(to, name);
		if (statSync(path).isDirectory()) { copyTests(path, target); continue; }
		if (!/\.(m?js|ts)$/.test(name)) { cpSync(path, target); continue; }
		const up = relative(dirname(target), root).split("\\").join("/");
		let text = read(path);
		// Same specifiers pi-repl's tests use, relative to their new location.
		text = text.replace(/(["'`(])\.\.\/index\.ts/g, (_, q) => `${q}${up}/src/pi-repl.ts`)
			.replace(/(["'`(])\.\.\/shared\//g, (_, q) => `${q}${up}/src/shared/`)
			.replace(/(["'])@earendil-works\/pi-coding-agent\1/g, (_, q) => `${q}${up}/src/pi-compat/index.ts${q}`)
			// Tests that run a script with the repository root as its working directory.
			.replace(/new URL\("\.\.", import\.meta\.url\)/g, `new URL("${up}/", import.meta.url)`)
			.replace(/(["'])\.\/index\.ts\1/g, (_, q) => `${q}./src/pi-repl.ts${q}`);
		if (/@earendil-works\//.test(text)) throw new Error(`${path} imports another Pi package; extend this script.`);
		writeFileSync(target, text);
	}
};
copyTests(join(upstream, "test"), testRoot);
writeFileSync(join(testRoot, "README.md"), `pi-repl's own test suite, copied by scripts/sync-from-pi-repl.mjs from pi-repl ${pkg.version} (${commit}).\nOnly import paths differ. Run with \`npm run test:upstream\`.\n`);

console.log(`Synced from pi-repl ${pkg.version} (${commit}); Pi helpers from pi-coding-agent ${piAgentVersion} and pi-ai ${piAiVersion}.`);
